"""Write or check the table of contents of nvsnap's maintained docs.

The TOC lists the ``##`` and ``###`` headings (outside code fences) as links,
between two marker comments placed right before the first ``##`` heading:

    <!-- toc: generated by scripts/docs/docs-toc.py; edit the headings, not this list -->
    **Contents**
    - [Heading](#heading)
      - [Sub heading](#sub-heading)
    <!-- /toc -->

Anchors use the slug and duplicate numbering of check-doc-links.py (GitHub's),
so a TOC link resolves exactly as a cross-file link would.

Usage: ``scripts/docs/docs-toc.py [--check] [FILE ...]``. With no FILE, every
git-tracked Markdown file under ``docs/`` except the frozen
``docs/results/``. ``--check`` changes nothing and exits 1 when a file's
TOC is missing or differs from its headings.

A file gets a TOC when it has at least two listable headings; a file with
fewer must carry none. ``<!-- toc-depth: 2 -->`` anywhere in a file lists
``##`` headings only (for very long documents).
"""
from __future__ import annotations

import importlib.util
import pathlib
import re
import subprocess
import sys

HERE = pathlib.Path(__file__).resolve().parent
NVSNAP = HERE.parents[1]
_spec = importlib.util.spec_from_file_location("check_doc_links", HERE / "check-doc-links.py")
assert _spec and _spec.loader
_links = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_links)

BEGIN = "<!-- toc: generated by scripts/docs/docs-toc.py; edit the headings, not this list -->"
END = "<!-- /toc -->"
BLOCK = re.compile(re.escape(BEGIN) + r".*?" + re.escape(END) + r"\n*", re.S)
DEPTH = re.compile(r"<!--\s*toc-depth:\s*([23])\s*-->")
FENCE = ("```", "~~~")


def headings(text: str) -> list[tuple[int, str, str]]:
    """(level, display text, anchor) for every heading, numbered like GitHub."""
    seen: dict[str, int] = {}
    out = []
    for line in _links.strip_fences(text).splitlines():
        m = _links.HEADING.match(line)
        if not m:
            continue
        level = len(line) - len(line.lstrip("#"))
        s = _links.slug(m.group(1))
        n = seen.get(s, 0)
        seen[s] = n + 1
        display = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", m.group(1)).strip()
        out.append((level, display, s if n == 0 else f"{s}-{n}"))
    return out


def entries(text: str) -> list[str]:
    m = DEPTH.search(text)
    deepest = int(m.group(1)) if m else 3
    return [("  " if level == 3 else "") + f"- [{display}](#{anchor})"
            for level, display, anchor in headings(BLOCK.sub("", text))
            if 2 <= level <= deepest]


def render(text: str) -> str:
    body = BLOCK.sub("", text)
    listed = entries(body)
    if len(listed) < 2:
        return body
    block = "\n".join([BEGIN, "**Contents**", "", *listed, END]) + "\n\n"
    in_fence = False
    pos = 0
    for line in body.splitlines(keepends=True):
        if line.lstrip().startswith(FENCE):
            in_fence = not in_fence
        elif not in_fence and line.startswith(("## ", "### ")):
            break
        pos += len(line)
    return body[:pos] + block + body[pos:]


def maintained() -> list[pathlib.Path]:
    out = subprocess.run(["git", "-C", str(NVSNAP), "ls-files", "--", "docs/*.md"],
                         check=True, capture_output=True, text=True).stdout
    return sorted(NVSNAP / p for p in out.splitlines()
                  if p and not p.startswith(_links.FROZEN))


def main(argv: list[str]) -> int:
    check = "--check" in argv
    files = [pathlib.Path(a) for a in argv if a != "--check"] or maintained()
    stale = []
    for f in files:
        text = f.read_text(encoding="utf-8")
        new = render(text)
        if new == text:
            continue
        if check:
            stale.append(str(f))
        else:
            f.write_text(new, encoding="utf-8")
            print(f"toc: {f}")
    if stale:
        print("missing or stale TOC (run scripts/docs/docs-toc.py):\n  " + "\n  ".join(stale), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
